// Emit one item per uploaded file, carrying its date (from the filename) and its binary.
const item = $('On form submission').first();
const bin = item.binary || {};
const out = [];
for (const key of Object.keys(bin)) {
  const b = bin[key];
  const name = String(b.fileName || key);
  const m = name.match(/(\d{4})-(\d{2})-(\d{2})/);
  out.push({
    json: { date: m ? `${m[1]}-${m[2]}-${m[3]}` : '', fileName: name },
    binary: { data: b },
  });
}
if (out.length < 2) {
  throw new Error('Upload at least two days of files from the week.');
}
return out;

// Attach each row's date (via pairedItem -> Split files), then compute per-owner weekly stats.
const files = $('Split files').all();
const dateForIndex = (idx) => (files[idx] && files[idx].json && files[idx].json.date) || '';

const rows = $input.all().map((it) => {
  const pi = it.pairedItem;
  let idx = 0;
  if (Array.isArray(pi)) idx = (pi[0] && pi[0].item) || 0;
  else if (pi && typeof pi === 'object') idx = pi.item || 0;
  else if (typeof pi === 'number') idx = pi;
  return {
    date: dateForIndex(idx),
    owner: String(it.json['Assignment'] ?? '').trim(),
    ticket: String(it.json['Overdue Tickets'] ?? '').trim(),
  };
}).filter((r) => r.owner && r.ticket && r.date);

const dates = [...new Set(rows.map((r) => r.date))].sort();
const first = dates[0];
const last = dates[dates.length - 1];

const byOwnerDate = new Map();
for (const r of rows) {
  if (!byOwnerDate.has(r.owner)) byOwnerDate.set(r.owner, new Map());
  const dm = byOwnerDate.get(r.owner);
  if (!dm.has(r.date)) dm.set(r.date, new Set());
  dm.get(r.date).add(r.ticket);
}

const perOwner = [];
for (const owner of [...byOwnerDate.keys()].sort()) {
  const dm = byOwnerDate.get(owner);
  const startSet = dm.get(first) || new Set();
  const endSet = dm.get(last) || new Set();
  const union = new Set();
  for (const s of dm.values()) for (const t of s) union.add(t);
  const persistent = [...union].filter((t) => dates.every((d) => (dm.get(d) || new Set()).has(t))).sort();
  const added = [...endSet].filter((t) => !startSet.has(t)).sort();
  const cleared = [...startSet].filter((t) => !endSet.has(t)).sort();
  const transient = [...union].filter((t) => !startSet.has(t) && !endSet.has(t)).sort();
  perOwner.push({
    owner, start: startSet.size, end: endSet.size, net: endSet.size - startSet.size,
    added, cleared, persistent, transient,
  });
}

const totalStart = perOwner.reduce((a, o) => a + o.start, 0);
const totalEnd = perOwner.reduce((a, o) => a + o.end, 0);
const netTotal = totalEnd - totalStart;

const lines = perOwner.map((o) =>
  `- ${o.owner}: start ${o.start}, end ${o.end}, net ${o.net >= 0 ? '+' : ''}${o.net}; ` +
  `new [${o.added.join(', ') || 'none'}]; cleared [${o.cleared.join(', ') || 'none'}]; ` +
  `overdue-all-week [${o.persistent.join(', ') || 'none'}]; came-and-went [${o.transient.join(', ') || 'none'}]`);

const prompt =
`You are a security operations analyst. Using ONLY the data below, write a concise weekly report on Network Engineering overdue vulnerability tickets. Do not invent or alter any numbers or ticket IDs. 3-5 short paragraphs, professional tone. Cover: the overall trend across the week, which owners improved or worsened (cite their net change), notable tickets (newly overdue, cleared, or overdue all week), and one or two takeaways.

Week: ${first} to ${last} (${dates.length} daily snapshots).
Team totals: start ${totalStart} overdue, end ${totalEnd} overdue, net ${netTotal >= 0 ? '+' : ''}${netTotal}.

Per owner:
${lines.join('\n')}`;

return [{ json: { prompt, perOwner, first, last, days: dates.length, totalStart, totalEnd } }];

// Combine the AI narrative with a per-owner table into a downloadable HTML report.
const a = $('Analyze week').first().json;
let narrative = '';
try {
  const c = $('Write report').first().json;
  narrative = String(c.text ?? c.output ?? c.response ?? '').trim();
} catch (e) { narrative = ''; }
if (!narrative) narrative = '(AI narrative unavailable — check the Azure OpenAI credential and deployment on the "Azure OpenAI Chat Model" node.)';

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const narrativeHtml = esc(narrative).split(/\n\n+/).map((p) => `<p>${p.replace(/\n/g, '<br>')}</p>`).join('\n');

const rowsHtml = (a.perOwner || []).map((o) => `
  <tr>
    <td>${esc(o.owner)}</td>
    <td class="n">${o.start}</td>
    <td class="n">${o.end}</td>
    <td class="n ${o.net > 0 ? 'up' : (o.net < 0 ? 'down' : '')}">${o.net >= 0 ? '+' : ''}${o.net}</td>
    <td>${esc((o.added || []).join(', '))}</td>
    <td>${esc((o.cleared || []).join(', '))}</td>
    <td>${esc((o.persistent || []).join(', '))}</td>
  </tr>`).join('');

const html = `<!doctype html><html><head><meta charset="utf-8">
<title>TVM weekly report ${esc(a.first)} to ${esc(a.last)}</title>
<style>
body{font-family:Segoe UI,Arial,sans-serif;max-width:920px;margin:24px auto;padding:0 16px;color:#1b1b1b}
h1{font-size:20px;margin-bottom:2px} h2{font-size:15px;margin-top:28px}
.sub{color:#666;font-size:13px}
table{border-collapse:collapse;width:100%;font-size:13px;margin-top:8px}
th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;vertical-align:top}
th{background:#f3f4f6} td.n{text-align:right} .up{color:#b00020} .down{color:#0a7d33}
p{line-height:1.5}
</style></head><body>
<h1>TVM Overdue Tickets — Weekly Report</h1>
<div class="sub">${esc(a.first)} to ${esc(a.last)} · ${a.days} snapshots · team ${a.totalStart} &rarr; ${a.totalEnd} overdue</div>
<h2>Summary</h2>
${narrativeHtml}
<h2>By owner</h2>
<table>
<tr><th>Owner</th><th>Start</th><th>End</th><th>Net</th><th>New overdue</th><th>Cleared</th><th>Overdue all week</th></tr>
${rowsHtml}
</table>
</body></html>`;

const fileName = `tvm-weekly-report-${a.first}-to-${a.last}.html`;
return [{
  json: { fileName },
  binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName, fileExtension: 'html' } },
}];
